'use strict';

// MODULES //

var tape = require( 'tape' );
var isAlmostSameValue = require( '@stdlib/assert/is-almost-same-value' );
var isnan = require( '@stdlib/math/base/assert/is-nan' );
var PINF = require( '@stdlib/constants/float64/pinf' );
var NINF = require( '@stdlib/constants/float64/ninf' );
var variance = require( './../lib' );


// FIXTURES //

var smallMuSmallSigma = require( './fixtures/python/small_mu_small_sigma.json' );
var smallMuLargeSigma = require( './fixtures/python/small_mu_large_sigma.json' );
var largeMuSmallSigma = require( './fixtures/python/large_mu_small_sigma.json' );
var largeMuLargeSigma = require( './fixtures/python/large_mu_large_sigma.json' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof variance, 'function', 'main export is a function' );
	t.end();
});

tape( 'if provided `NaN` for any parameter, the function returns `NaN`', function test( t ) {
	var y = variance( NaN, 1.0 );
	t.strictEqual( isnan( y ), true, 'returns expected value' );
	y = variance( 1.0, NaN );
	t.strictEqual( isnan( y ), true, 'returns expected value' );
	t.end();
});

tape( 'if provided a nonpositive `sigma`, the function returns `NaN`', function test( t ) {
	var y;

	y = variance( 2.0, 0.0 );
	t.strictEqual( isnan( y ), true, 'returns expected value' );

	y = variance( 2.0, -1.0 );
	t.strictEqual( isnan( y ), true, 'returns expected value' );

	y = variance( 1.0, NINF );
	t.strictEqual( isnan( y ), true, 'returns expected value' );

	y = variance( PINF, NINF );
	t.strictEqual( isnan( y ), true, 'returns expected value' );

	y = variance( NINF, NINF );
	t.strictEqual( isnan( y ), true, 'returns expected value' );

	y = variance( NaN, NINF );
	t.strictEqual( isnan( y ), true, 'returns expected value' );

	t.end();
});

tape( 'the function returns the variance of an anglit distribution for small `mu` and small `sigma`', function test( t ) {
	var expected;
	var sigma;
	var mu;
	var y;
	var i;

	expected = smallMuSmallSigma.expected;
	mu = smallMuSmallSigma.mu;
	sigma = smallMuSmallSigma.sigma;
	for ( i = 0; i < expected.length; i++ ) {
		y = variance( mu[i], sigma[i] );
		t.strictEqual( isAlmostSameValue( y, expected[i], 40 ), true, 'returns expected value' );
	}
	t.end();
});

tape( 'the function returns the variance of an anglit distribution for small `mu` and large `sigma`', function test( t ) {
	var expected;
	var sigma;
	var mu;
	var y;
	var i;

	expected = smallMuLargeSigma.expected;
	mu = smallMuLargeSigma.mu;
	sigma = smallMuLargeSigma.sigma;
	for ( i = 0; i < expected.length; i++ ) {
		y = variance( mu[i], sigma[i] );
		t.strictEqual( isAlmostSameValue( y, expected[i], 40 ), true, 'returns expected value' );
	}
	t.end();
});

